  int text_caret(float mouse_x, Rectangle area, const std::string& text) { const int text_x=static_cast<int>(area.x+3);int mouse=static_cast<int>(mouse_x);int best=mouse>text_x?mouse-text_x:text_x-mouse;int caret=0;for(int index=1;index<=static_cast<int>(text.size());++index){const int position=text_x+MeasureText(text.substr(0,index).c_str(),12);const int distance=mouse>position?mouse-position:position-mouse;if(distance<best){best=distance;caret=index;}}return caret; }
  void field(int id,const char* label, float x, float y, const std::string& value, float input_width=64) { DrawText(label,static_cast<int>(x+1),static_cast<int>(y+4),12,BLACK); const Rectangle area=box(x+96,y,input_width,21); DrawRectangleRec(area,RAYWHITE); sunken_frame(area); const auto& text=state.active==id?state.input:value; const int text_x=static_cast<int>(area.x+3); const std::size_t selection_start=state.input_anchor<state.input_cursor?state.input_anchor:state.input_cursor; const std::size_t selection_end=state.input_anchor<state.input_cursor?state.input_cursor:state.input_anchor; if(state.active==id&&state.input_selected&&selection_start!=selection_end){const int x1=text_x+MeasureText(state.input.substr(0,selection_start).c_str(),12),x2=text_x+MeasureText(state.input.substr(0,selection_end).c_str(),12);DrawRectangle(x1,static_cast<int>(area.y+3),x2-x1,14,Color{0,120,215,255});} DrawText(text.c_str(),text_x,static_cast<int>(area.y+4),12,BLACK); if(state.active==id&&state.input_selected&&selection_start!=selection_end){const int x1=text_x+MeasureText(state.input.substr(0,selection_start).c_str(),12);DrawText(state.input.substr(selection_start,selection_end-selection_start).c_str(),x1,static_cast<int>(area.y+4),12,RAYWHITE);} if(state.active==id&&!state.input_selected){const auto prefix=state.input.substr(0,state.input_cursor);const int caret=text_x+MeasureText(prefix.c_str(),12)+((state.input_cursor==state.input.size()&&!state.input.empty())?1:0);DrawLine(caret,static_cast<int>(area.y+3),caret,static_cast<int>(area.y+17),BLACK);} if(CheckCollisionPointRec(ui_mouse_position(),area)&&IsMouseButtonPressed(MOUSE_BUTTON_LEFT)){if(state.active!=id){state.active=id;state.input=value;}const int caret=text_caret(ui_mouse_position().x,area,state.input);state.input_cursor=static_cast<std::size_t>(caret);state.input_anchor=state.input_cursor;state.input_selected=false;state.input_dragging=true;if(id==0)state.random=false;} }
  std::string number(double value) { char result[32]; std::snprintf(result,sizeof(result),"%g",value); return result; }
  void spin_field(int id,const char* label,float x,float y,double& value,double step) { DrawText(label,static_cast<int>(x+1),static_cast<int>(y+4),12,BLACK); const Rectangle area=box(x+96,y,65,22),arrows=box(area.x+47,area.y+2,15,17); DrawRectangleRec(area,RAYWHITE); sunken_frame(area); draw_sprite(spin_sprite,static_cast<int>(arrows.x),static_cast<int>(arrows.y),15,17); const auto text=state.active==id?state.input:number(value); DrawText(text.c_str(),static_cast<int>(area.x+3),static_cast<int>(area.y+5),12,BLACK); if(CheckCollisionPointRec(ui_mouse_position(),arrows)&&IsMouseButtonReleased(MOUSE_BUTTON_LEFT)){value+=ui_mouse_position().y<arrows.y+8?step:-step;state.active=-1;} else if(CheckCollisionPointRec(ui_mouse_position(),box(area.x,area.y,47,22))&&IsMouseButtonReleased(MOUSE_BUTTON_LEFT)){state.active=id;state.input=number(value);} }
